INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('6d563d05-81bc-4378-a18b-352d496f41b9', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '26314a8e-94e8-4465-a762-76563e2f29f6', 'JEE_MAIN', 'SINGLE_MCQ', 'HARD', '[PYQ Ref #3] In an experiment, density $\rho = \frac{m}{L^3}$. If relative error in mass is $1.2\%$ and length is $0.8\%$, the maximum percentage error in density is:', '$\frac{\Delta \rho}{\rho} = \frac{\Delta m}{m} + 3\frac{\Delta L}{L} = 1.2\% + 3(0.8\%) = 3.6\%$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2023-S1-Q03', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
