INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('dbab78f7-f697-4f2c-ab63-d2ddf2e48d90', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', '92b8e738-34c4-4d4c-a5fb-54432f9ef7f3', 'NEET', 'SINGLE_MCQ', 'EASY', '[Variation 5] A projectile is launched with velocity $u$ at angle $\theta$ to the horizontal. The radius of curvature of its trajectory at the highest point is:', 'At the apex, $v = u \cos \theta$ and centripetal acceleration $a_c = g$. Hence $R = \frac{v^2}{g} = \frac{u^2 \cos^2 \theta}{g}$.', 'PREVIOUS_YEAR', 'NEET-2021-S1-Q05', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
