INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('f923faa0-ac58-4015-a073-0a2f97c3f149', 'a893beda-5696-470d-a9cb-468c3a249792', '4e60533d-2551-4fc4-ae44-7edcea8be3bc', 'cd3962ad-6fbe-4973-a7c1-ae48ab8b87fd', 'JEE_ADV', 'SINGLE_MCQ', 'ADVANCED', '[PYQ Ref #132] A particle is released from the apex of a smooth sphere of radius $R$. The height $h$ from the center at which it leaves the surface is:', 'Normal force $N = 0 \implies m g \cos \theta = \frac{m v^2}{R}$. Conservation of energy gives $\cos \theta = \frac{2}{3}$, so $h = \frac{2}{3} R$.', 'PREVIOUS_YEAR', 'JEE_ADV-2022-S2-Q12', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
