INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('833cd886-9843-4cd6-a8cc-cd37f4be8adb', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', 'ed2ea8de-9184-4e5d-a43d-2cabbf253d55', 'JEE_MAIN', 'SINGLE_MCQ', 'EASY', '[PYQ Ref #349] The dimensional formula of magnetic permeability $\mu_0$ in terms of fundamental quantities $[M, L, T, A]$ is:', 'From Ampere''s force law $F = \frac{\mu_0 I_1 I_2 L}{2\pi r}$, $[\mu_0] = [F]/[I^2] = [M L T^{-2} A^{-2}]$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2021-S1-Q19', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
