INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('a6cd4956-1e8f-4097-ae39-2b11de56e5cc', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', 'ed2ea8de-9184-4e5d-a43d-2cabbf253d55', 'NEET', 'SINGLE_MCQ', 'EASY', '[PYQ Ref #465] In an experiment, density $\rho = \frac{m}{L^3}$. If relative error in mass is $1.2\%$ and length is $0.8\%$, the maximum percentage error in density is:', '$\frac{\Delta \rho}{\rho} = \frac{\Delta m}{m} + 3\frac{\Delta L}{L} = 1.2\% + 3(0.8\%) = 3.6\%$.', 'PREVIOUS_YEAR', 'NEET-2025-S1-Q15', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
