INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('e2305019-b0eb-4468-af05-bb054a057e29', 'a893beda-5696-470d-a9cb-468c3a249792', '2887ac65-5089-403e-a567-fe9b4ec2fa8d', '6a87259c-d885-43ab-a837-da398690a3e0', 'JEE_MAIN', 'SINGLE_MCQ', 'ADVANCED', '[PYQ Ref #728] A parallel plate capacitor $C_0$ is filled with two dielectrics of constants $K_1 = 3$ and $K_2 = 6$ of equal thickness $d/2$. The new capacitance is:', 'Series combination: $C_{eq} = \frac{C_1 C_2}{C_1 + C_2} = \frac{(2 K_1 C_0)(2 K_2 C_0)}{2(K_1 + K_2) C_0} = \frac{2 \times 3 \times 6}{3 + 6} C_0 = 4 C_0$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2018-S2-Q08', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
