INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('fb932537-0d25-43ba-aa00-23dbfa792d9c', '4cc612fd-34dd-4420-a2a8-9df2e5c7eb0d', '1b1ceeae-5127-4d38-a56b-5dede659fe36', 'c275a667-87d3-4dce-a2e5-d3be66c2602a', 'JEE_ADV', 'SINGLE_MCQ', 'ADVANCED', '[PYQ Ref #1392] If two fair dice are rolled, the probability that the sum of the numbers is greater than $9$ given that the first die shows a $5$ is:', 'Sample space with first die 5: { (5,1), ..., (5,6) } (6 outcomes). Sum > 9: (5,5) and (5,6) (2 outcomes). Probability = $2/6 = 1/3$.', 'PREVIOUS_YEAR', 'JEE_ADV-2018-S2-Q12', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
