INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('c581cffd-0053-44f6-ae04-a51fb7ba2df2', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '09747640-8048-4077-a28d-da85c7cef9a0', 'JEE_MAIN', 'SINGLE_MCQ', 'ADVANCED', '[Variation 20] If force $F$, velocity $v$ and time $T$ are fundamental units, the dimension of mass $20M$ is:', '$F = M a = M \frac{v}{T} \implies M = [F v^{-1} T]$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2022-S2-Q08', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
