INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('5b790aa9-4153-4621-aadc-f13dcd0b160a', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', 'fa3a6014-045a-4cd9-a49b-e2982bec18b4', 'NEET', 'SINGLE_MCQ', 'MEDIUM', '[Variation 15] A particle moves along the x-axis with acceleration $a = 6t + 2 \text{ m/s}^2$. If $v(0) = 4 \text{ m/s}$ and $x(0) = 0$, its position at $t = 2\text{ s}$ is:', '$v(t) = 3t^2 + 2t + 4$. Integrating: $x(t) = t^3 + t^2 + 4t$. At $t = 2$, $x(2) = 8 + 4 + 8 = 20\text{ m}$.', 'PREVIOUS_YEAR', 'NEET-2024-S2-Q20', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
