INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('6c4c024e-f5c7-422c-a21e-d663362988cb', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '26314a8e-94e8-4465-a762-76563e2f29f6', 'JEE_MAIN', 'SINGLE_MCQ', 'HARD', '[PYQ Ref #2323] The dimensional formula of magnetic permeability $\mu_0$ in terms of fundamental quantities $[M, L, T, A]$ is:', 'From Ampere''s force law $F = \frac{\mu_0 I_1 I_2 L}{2\pi r}$, $[\mu_0] = [F]/[I^2] = [M L T^{-2} A^{-2}]$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2023-S1-Q13', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
