INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('1e281359-d176-4624-a1b1-06c09e9d541f', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '09747640-8048-4077-a28d-da85c7cef9a0', 'NEET', 'SINGLE_MCQ', 'ADVANCED', '[PYQ Ref #2440] The dimensional formula of magnetic permeability $\mu_0$ in terms of fundamental quantities $[M, L, T, A]$ is:', 'From Ampere''s force law $F = \frac{\mu_0 I_1 I_2 L}{2\pi r}$, $[\mu_0] = [F]/[I^2] = [M L T^{-2} A^{-2}]$.', 'PREVIOUS_YEAR', 'NEET-2018-S2-Q10', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
