INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('5ea751e8-17c3-4dee-a90a-1737c2431782', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', '4a2efc4f-4cb9-4bb4-ab03-edc8adbbe4ea', 'NEET', 'SINGLE_MCQ', 'HARD', '[Variation 2] A projectile is launched with velocity $u$ at angle $\theta$ to the horizontal. The radius of curvature of its trajectory at the highest point is:', 'At the apex, $v = u \cos \theta$ and centripetal acceleration $a_c = g$. Hence $R = \frac{v^2}{g} = \frac{u^2 \cos^2 \theta}{g}$.', 'PREVIOUS_YEAR', 'NEET-2023-S1-Q05', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.question_options (id, question_id, option_key, content_latex, is_correct, order_index) VALUES ('f358f1f2-e1b8-4eff-ab40-110b24e41b29', '5ea751e8-17c3-4dee-a90a-1737c2431782', 'A', '$\frac{u^2 \sin^2 \theta}{g}$', FALSE, 1) ON CONFLICT (question_id, option_key) DO NOTHING;
