INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('b84c85c5-8d25-42ea-aaae-828509cfff09', 'a893beda-5696-470d-a9cb-468c3a249792', '59391119-0232-40e6-a300-3225f7e31281', '776dd101-756f-4eaf-abcf-b45497651051', 'JEE_ADV', 'SINGLE_MCQ', 'EASY', '[Variation 4] A block of mass $m$ is on an inclined plane of angle $\theta$. If coefficient of static friction is $\mu_s = \tan \theta$, the minimum horizontal force required to prevent sliding is:', 'Since $\mu_s = \tan \theta$, the angle of repose matches incline angle, so gravity and friction are in static equilibrium.', 'PREVIOUS_YEAR', 'JEE_ADV-2021-S1-Q07', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
