INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('2fa8decf-22a9-43da-a6ab-94cc3bf7a9ff', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', '3c450c78-e5df-4abe-ab5d-5dca45b64529', 'JEE_ADV', 'SINGLE_MCQ', 'ADVANCED', '[Variation 12] A particle moves along the x-axis with acceleration $a = 6t + 2 \text{ m/s}^2$. If $v(0) = 4 \text{ m/s}$ and $x(0) = 0$, its position at $t = 2\text{ s}$ is:', '$v(t) = 3t^2 + 2t + 4$. Integrating: $x(t) = t^3 + t^2 + 4t$. At $t = 2$, $x(2) = 8 + 4 + 8 = 20\text{ m}$.', 'PREVIOUS_YEAR', 'JEE_ADV-2018-S2-Q02', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
