INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('073efa56-a840-4a9e-a1ff-4dfd271ff0f0', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '26314a8e-94e8-4465-a762-76563e2f29f6', 'JEE_MAIN', 'SINGLE_MCQ', 'HARD', '[Variation 6] If force $F$, velocity $v$ and time $T$ are fundamental units, the dimension of mass $6M$ is:', '$F = M a = M \frac{v}{T} \implies M = [F v^{-1} T]$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2023-S1-Q11', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
