INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('ccbcab93-10fe-42f3-ada5-812ae2633fd7', 'a893beda-5696-470d-a9cb-468c3a249792', '4e60533d-2551-4fc4-ae44-7edcea8be3bc', '48d4b5fd-e31a-4271-a81c-de0c69735d1a', 'JEE_MAIN', 'SINGLE_MCQ', 'EASY', '[PYQ Ref #3261] A particle is released from the apex of a smooth sphere of radius $R$. The height $h$ from the center at which it leaves the surface is:', 'Normal force $N = 0 \implies m g \cos \theta = \frac{m v^2}{R}$. Conservation of energy gives $\cos \theta = \frac{2}{3}$, so $h = \frac{2}{3} R$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2021-S1-Q21', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
