INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('db486008-1f03-4dec-a9b1-ebb8714d35aa', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', '4a2efc4f-4cb9-4bb4-ab03-edc8adbbe4ea', 'JEE_MAIN', 'SINGLE_MCQ', 'HARD', '[Variation 6] A projectile is launched with velocity $u$ at angle $\theta$ to the horizontal. The radius of curvature of its trajectory at the highest point is:', 'At the apex, $v = u \cos \theta$ and centripetal acceleration $a_c = g$. Hence $R = \frac{v^2}{g} = \frac{u^2 \cos^2 \theta}{g}$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2023-S1-Q03', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
