INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('66f4fb5a-293d-4540-ab7a-fd929ad2f3b5', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '09747640-8048-4077-a28d-da85c7cef9a0', 'NEET', 'SINGLE_MCQ', 'ADVANCED', '[PYQ Ref #4180] The dimensional formula of magnetic permeability $\mu_0$ in terms of fundamental quantities $[M, L, T, A]$ is:', 'From Ampere''s force law $F = \frac{\mu_0 I_1 I_2 L}{2\pi r}$, $[\mu_0] = [F]/[I^2] = [M L T^{-2} A^{-2}]$.', 'PREVIOUS_YEAR', 'NEET-2022-S2-Q10', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.question_options (id, question_id, option_key, content_latex, is_correct, order_index) VALUES ('3aea32e1-bf18-4319-ac07-388338c7fac9', '66f4fb5a-293d-4540-ab7a-fd929ad2f3b5', 'A', '$[M L^2 T^{-2} A^{-1}]$', FALSE, 1) ON CONFLICT (question_id, option_key) DO NOTHING;
