INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('8934448c-fe2a-4ae6-abc0-f57f954442b0', 'a893beda-5696-470d-a9cb-468c3a249792', 'c25f3c81-8c47-4a24-aceb-a1118f2088e1', '92b8e738-34c4-4d4c-a5fb-54432f9ef7f3', 'JEE_MAIN', 'SINGLE_MCQ', 'EASY', '[Variation 1] A projectile is launched with velocity $u$ at angle $\theta$ to the horizontal. The radius of curvature of its trajectory at the highest point is:', 'At the apex, $v = u \cos \theta$ and centripetal acceleration $a_c = g$. Hence $R = \frac{v^2}{g} = \frac{u^2 \cos^2 \theta}{g}$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2021-S1-Q11', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.question_options (id, question_id, option_key, content_latex, is_correct, order_index) VALUES ('65856b94-fe07-4e0e-acd5-7985fde0f3bc', '8934448c-fe2a-4ae6-abc0-f57f954442b0', 'A', '$\frac{u^2 \cos^2 \theta}{g}$', TRUE, 1) ON CONFLICT (question_id, option_key) DO NOTHING;
