INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('e999423e-0a50-4de4-aab2-b80fc5058c6a', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', 'ed2ea8de-9184-4e5d-a43d-2cabbf253d55', 'JEE_MAIN', 'SINGLE_MCQ', 'EASY', '[PYQ Ref #4641] In an experiment, density $\rho = \frac{m}{L^3}$. If relative error in mass is $1.2\%$ and length is $0.8\%$, the maximum percentage error in density is:', '$\frac{\Delta \rho}{\rho} = \frac{\Delta m}{m} + 3\frac{\Delta L}{L} = 1.2\% + 3(0.8\%) = 3.6\%$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2025-S1-Q21', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
