INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('3b5a872d-461c-4029-a2a0-7bbcc143fb0c', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '465db1f2-92d3-42d4-aab5-bb7a532a4bfb', 'JEE_ADV', 'SINGLE_MCQ', 'MEDIUM', '[PYQ Ref #4642] The dimensional formula of magnetic permeability $\mu_0$ in terms of fundamental quantities $[M, L, T, A]$ is:', 'From Ampere''s force law $F = \frac{\mu_0 I_1 I_2 L}{2\pi r}$, $[\mu_0] = [F]/[I^2] = [M L T^{-2} A^{-2}]$.', 'PREVIOUS_YEAR', 'JEE_ADV-2024-S2-Q22', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
