INSERT INTO public.questions (id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty, content_latex, explanation_latex, source_type, source_reference, status, is_active) VALUES ('1e80dc6c-16cc-4db8-aa35-821bd9552bc7', 'a893beda-5696-470d-a9cb-468c3a249792', '189a2fc7-f908-4bee-aec1-5e6d37461e48', '465db1f2-92d3-42d4-aab5-bb7a532a4bfb', 'JEE_MAIN', 'SINGLE_MCQ', 'MEDIUM', '[PYQ Ref #4758] In an experiment, density $\rho = \frac{m}{L^3}$. If relative error in mass is $1.2\%$ and length is $0.8\%$, the maximum percentage error in density is:', '$\frac{\Delta \rho}{\rho} = \frac{\Delta m}{m} + 3\frac{\Delta L}{L} = 1.2\% + 3(0.8\%) = 3.6\%$.', 'PREVIOUS_YEAR', 'JEE_MAIN-2020-S2-Q18', 'APPROVED', TRUE) ON CONFLICT (id) DO NOTHING;
